namespace Fesh;

// What each friend says on reaching a heart (1.45.1): five lines each, one per heart, small talk at one and "you belong here"
// at five. Drafted with Codex, ASCII only, no spoilers. Shown after the conversation that earns the heart, and listed on the
// Friends panel (hover a card) so they can be read again.
partial class Game
{
    static readonly Dictionary<string, string[]> HeartLines = new()
    {
        ["tomas"] = new[] { "Mind that loose board. I've got a nail set aside for it.", "Sit a spell. This net can spare me long enough to hear about your catch.", "Hold this end, will you? You've learned when a rope needs slack.", "Some mornings I mend the same stretch of net just to have work for my hands.", "Your place is by the fire, anak. Bring your catch over; we'll sort supper." },
        ["pip"] = new[] { "Morning! Fresh hooks on the left. Admiring them is still free.", "I saved the straightest bit of string for your parcel. Shopkeeper's privilege.", "Watch the stall while I count these? You know where everything belongs.", "I talk a big bargain, but a quiet stall makes for a long afternoon.", "Your usual spot behind the counter is clear. Come help me grumble over the accounts." },
        ["lira"] = new[] { "Something smells good, no? I put ginger in the pot this morning.", "You came at the right time. Taste this broth before I call everyone.", "Take these bowls to the table. You know who likes an extra spoonful.", "I cook a little too much when the house feels quiet. Hard habit to put down.", "Get your bowl from the shelf, anak. You don't have to wait for an invitation here." },
        ["niko"] = new[] { "Seen my bangus pond? Finest splash in the village. I'll stand by that.", "Come watch feeding time. I can nearly tell which fish will arrive first.", "Keep an eye on that corner of the pond with me. You notice things I miss.", "All my boasting gets a bit thin on a poor fishing day. Glad you stay to listen.", "We've room for two names on this pond's bragging rights. You're one of us now." },
        ["maya"] = new[] { "That's guso on the lines. I spend half my morning checking the ties.", "Come sit by the lagoon. I've finally untangled enough cord to find the bench.", "Would you check this tie? Your fingers have learned the work.", "Sometimes I worry over one loose tie all evening. Growing things makes me fret.", "Leave your basket beside mine. There's room for your things here every day." },
        ["tala"] = new[] { "I check the bubo traps before I settle down to watch the mangroves.", "Stay a little. This is my favorite place to wait for the fireflies.", "Sit quietly beside me. You've learned to spot the first little light.", "People think I like being alone here. Often I just don't know how to ask for company.", "Come along, apo. Our evening round feels incomplete until you're walking beside me." },
        ["isay"] = new[] { "A fisher! Excellent. My pupils have enough questions to fill your boat.", "I've kept one question for you. You always give an answer worth discussing.", "Will you listen to their fish reports? They trust what you've seen at sea.", "I rehearse new lessons to an empty room. Even teachers worry about getting things right.", "Your chair is by my desk. The children already ask when you're coming home to visit." },
        ["mila"] = new[] { "These abaca bundles keep my fingers busy. Sit where the loose fibers won't tickle you.", "Bring that stool closer. I'll show you the tie my lola taught me.", "Tie this bundle while I start the next. Your knots hold well.", "I plant pili trees slowly these days. I like thinking of someone resting beneath them.", "Come sit under our pili tree, anak. I've watched it grow, and I've watched you settle in." },
        ["ben"] = new[] { "Morning. I'm copying the station readings into the log.", "You can sit here while I finish. I leave this chair out for visitors.", "Would you read those numbers back? A second careful pair of eyes helps.", "I practice explaining the readings before anyone arrives. The numbers come easier than the words.", "I put a second cup beside the logbook. It seemed odd to keep calling you a visitor." },
        ["joy"] = new[] { "Welcome to the sanctuary. We give the turtles plenty of room here.", "Come to the lookout with me. I like having someone to share a quiet watch.", "Tell me what you noticed today. Your observations belong in our watch notes.", "After everyone leaves, I sometimes stay just to hear the water without having to explain it.", "There's a place beside me on every watch. You've become part of this shore's family." },
        ["rosa"] = new[] { "Bright morning for the salt beds. These little crystals catch every bit of sun.", "I've cleared a place in the shade. Sorting fish goes better with company.", "Help me count the rack trays? I trust your tally as much as mine.", "My hands keep sorting even when the work is done. Sitting still takes practice.", "Put your basket with ours, anak. We'll finish the racks, then eat together." },
        ["pacing"] = new[] { "Care for sungka? These shells have heard a great deal of boasting.", "I've set the board out. Your side is the one with the smooth little shell.", "Read the tide table with me, apo. You take your time with the details.", "I still reach for a shell when I'm worried. Its edges have grown smooth with all my thinking.", "The board stays here for you, apo. Walk in and set out our shells whenever you come home." },
        ["dado"] = new[] { "That's my paraw. Yes, I polished that bit twice. A boat ought to look ready.", "Come see the sail. I want your opinion before I start praising it myself.", "Check my gear list with me? Racing makes me eager; you help me stay thorough.", "Before a race, I go quiet for a while. All that cheering feels very far away then.", "Find us after the regatta. My family's supper always has a place for you." },
        ["celso"] = new[] { "Welcome to Parola. I've just finished cleaning the lighthouse windows.", "Come rest your feet. The kettle is my reward for finishing the stairs.", "Would you check my supply list? You've come to know this place well.", "The long evenings used to weigh on me. I started keeping a cup ready for company.", "Your cup is on the shelf beside mine. You belong here, even on days there's nothing to mend." },
        ["sela"] = new[] { "The children have been brushing the trail's rock face. Every little patch gets a discussion.", "Walk a little way with us. They want to show you what they noticed.", "Would you hear their explanations first? You've learned to let them find their own words.", "I worry when a child says they aren't clever. I remember believing that about myself.", "Come along with our little crowd. They count you among the people who belong on this trail." },
        ["lorna"] = new[] { "The dryer gets its warmth from the springs. I've been checking trays all morning.", "Sit here while I finish the labels. I like hearing about your day's catch.", "Will you check these labels with me? You catch the little slips I read straight past.", "I used to eat lunch standing up beside the trays. Company is teaching me to take a proper break.", "Your bowl is beside mine. Around here, you get called for lunch with the rest of the family." },
        ["ambo"] = new[] { "Watching the sandbar? I check the water before I give anyone a time to start back.", "Sit beside me. You can see why I keep looking at that same patch of shore.", "Tell me what the water is doing. I trust you to look carefully before you answer.", "I count everyone back twice. Only then can I settle down and enjoy my supper.", "I'll be glad to see you at our table tonight, anak. Your place is already set." },
        ["iyo"] = new[] { "Hear the kalutang? The children always ask to play the loud part first.", "Take this pair. We'll try one slow rhythm before they recruit you for the whole tune.", "Keep the beat for us. They listen when your sticks begin.", "I tap rhythms on my knees when the house is quiet. Sometimes I miss the practice noise.", "Your sticks are with ours. Come in, find your place, and we'll make the house ring." },
        ["nita"] = new[] { "A few chewed lime leaves mean the butterfly nursery has been busy.", "Come sit while I mend this net. There's room to stretch your legs beside the basket.", "Watch this section of net with me. Your eyes find a missed loop faster than mine.", "Some days I leave one small tear for morning. I'm learning that work can wait while we talk.", "Your chair stays beside my basket, anak. This house has room for your quiet days too." },
    };

    static string HeartLine(string id, int hearts) =>
        HeartLines.TryGetValue(id, out var l) && hearts >= 1 && hearts <= l.Length ? l[hearts - 1] : null;
}
